// Comptes dont le sens normal diffère de la règle générale de leur classe, ou qui sont légitimement à solde
// variable (débiteur OU créditeur selon les cas réels : report à nouveau, résultat, compte de l'exploitant...)
// et ne doivent donc jamais être signalés comme "incohérents" par le contrôle automatique.
var PCG_SENS_OVERRIDES = {"109":"D","103":null,"104":null,"12":null,"129":null,"13":null,"1301":null,"1309":null,"139":null};

// Recherche par préfixe décroissant (4, 3, puis 2 chiffres) dans un objet clé = préfixe de n° de compte.
// Permet de faire correspondre un compte détaillé (ex: 4111, 1013) à sa fiche de compte principal (41, 101...).
function pcgPrefixLookup(map, compte, maxLen){
    var s = String(compte || '').trim();
    if(!s) return null;
    var top = Math.min(s.length, maxLen || 4);
    for(var len = top; len >= 2; len--){
        var key = s.substring(0, len);
        if(Object.prototype.hasOwnProperty.call(map, key)) return { key: key, value: map[key] };
    }
    return null;
}
// Retourne la fiche détaillée (nom + éléments de contrôle) du compte, ou null si non répertorié.
function getFicheCompte(compte){
    var hit = pcgPrefixLookup(PCG_FICHES, compte, 4);
    return hit ? hit.value : null;
}
// Libellé lisible du sens de solde attendu ('D'/'C'/null) pour affichage dans la fiche compte.
function libelleSensPCG(sens){
    if(sens === 'D') return 'Débiteur';
    if(sens === 'C') return 'Créditeur';
    return 'Variable (débiteur ou créditeur selon les cas) — non contrôlé automatiquement';
}
// Affiche la fiche de contrôle d'un compte (sens attendu + éléments de contrôle / recoupements suggérés).
window.showFicheCompte = function(compte){
    var modal = document.getElementById('fiche-compte-modal');
    var titre = document.getElementById('fiche-compte-titre');
    var body = document.getElementById('fiche-compte-body');
    if(!modal || !titre || !body) return;
    var fiche = getFicheCompte(compte);
    var sens = expectedSensPCG(compte);
    var html = '<p style="margin-bottom:10px;"><strong>Sens normal attendu :</strong> ' + esc(libelleSensPCG(sens)) + '</p>';
    if(fiche && fiche.fonctionnement && fiche.fonctionnement.length){
        html += '<p style="margin-bottom:6px;"><strong>⚙️ Fonctionnement</strong> (contreparties normales — sens D/C attendu de la contrepartie, condensé) :</p>' +
            '<ul style="margin:0 0 14px 20px; padding:0;">' +
            fiche.fonctionnement.map(function(f){ return '<li style="margin-bottom:4px;">' + esc(f) + '</li>'; }).join('') +
            '</ul>';
    }
    if(fiche && fiche.controle && fiche.controle.length){
        html += '<p style="margin-bottom:6px;"><strong>🔍 Éléments de contrôle suggérés</strong> (recoupements à rechercher pour ce compte) :</p>' +
            '<ul style="margin:0 0 0 20px; padding:0;">' +
            fiche.controle.map(function(c){ return '<li style="margin-bottom:4px;">' + esc(c) + '</li>'; }).join('') +
            '</ul>';
    } else {
        html += '<p style="color:#888;">Aucun élément de contrôle spécifique répertorié pour ce compte dans le référentiel intégré.</p>';
    }
    html += '<p style="margin-top:14px; font-size:11px; color:#999;">Source : référentiel SYSCOHADA (fonctionnement et éléments de contrôle des comptes), intégré à l\'outil pour appuyer l\'analyse — ne remplace pas le jugement professionnel de l\'auditeur.</p>';
    titre.textContent = '📖 Compte ' + compte + (fiche ? ' — ' + fiche.name : '');
    body.innerHTML = html;
    modal.style.display = 'block';
};
window.closeFicheCompte = function(){
    var modal = document.getElementById('fiche-compte-modal');
    if(modal) modal.style.display = 'none';
};
// Clic délégué sur les lignes du Plan Comptable PCG SYSCOHADA : ouvre la fiche de contrôle du compte cliqué,
// sans avoir à modifier individuellement les centaines de lignes déjà présentes dans le tableau.
document.addEventListener('click', function(e){
    var row = e.target.closest ? e.target.closest('#pcg-syscohada tr.pcg-row') : null;
    if(!row) return;
    var firstCell = row.querySelector('td');
    var compte = firstCell ? firstCell.textContent.trim() : '';
    if(compte) showFicheCompte(compte);
});

// Nature de solde attendue par classe/préfixe de compte SYSCOHADA (D = débiteur, C = créditeur, null = nature variable, non contrôlée)
function expectedSensPCG(compte){
    // Exceptions connues (issues du référentiel détaillé) : contrôlées avant la règle générale par classe.
    var override = pcgPrefixLookup(PCG_SENS_OVERRIDES, compte, 4);
    if(override) return override.value;
    var c0 = String(compte).charAt(0);
    var c2 = String(compte).substring(0,2);
    if(c0 === '1') return 'C';                          // capitaux, réserves, emprunts
    if(c0 === '2') return (c2 === '28' || c2 === '29') ? 'C' : 'D'; // immobilisations brutes (D) / amortissements-provisions (C)
    if(c0 === '3') return 'D';                           // stocks
    if(c0 === '4'){
        if(c2 === '40') return 'C';                      // fournisseurs
        if(c2 === '41') return 'D';                      // clients
        if(c2 === '43') return 'C';                      // organismes sociaux
        return null;                                      // 42,44,45,46,47,48,49... : nature variable, non contrôlée
    }
    if(c0 === '5') return 'D';                            // trésorerie
    if(c0 === '6') return 'D';                            // charges
    if(c0 === '7') return 'C';                            // produits
    if(c0 === '8'){
        // Comptes HAO (Hors Activités Ordinaires) : 2e chiffre pair = produit HAO (C),
        // impair = charge HAO (D). Même règle que classifyGLCompte(), désormais appliquée
        // aussi au contrôle de sens de la balance (cf. guide SYSCOHADA : classes 6,7,8 = gestion).
        var d2 = parseInt(String(compte).charAt(1) || '0', 10);
        return (d2 % 2 === 0) ? 'C' : 'D';
    }
    return null;                                           // classe 9 et autres : nature variable
}
function coherencePCG(compte, soldeSigne){
    var attendu = expectedSensPCG(compte);
    if(attendu === null) return { html: '<span style="color:#999;">— (nature variable, non contrôlée)</span>', incoherent:false };
    if(soldeSigne === 0) return { html: '<span style="color:#999;">Solde nul</span>', incoherent:false };
    var reel = soldeSigne > 0 ? 'D' : 'C';
    if(reel === attendu) return { html: '<span class="status-ok">✓ Cohérent (attendu '+attendu+')</span>', incoherent:false };
    return { html: '<span style="color:#c0392b; font-weight:700;">⚠️ Incohérent — attendu '+attendu+', constaté '+reel+'</span>', incoherent:true };
}
function computeSelectionComptes(){
    var modeEl = document.getElementById('sel-comptes-mode');
    var mode = modeEl ? modeEl.value : 'abs';
    var seuil = seuils.planif || 0;
    var rows = balanceData.n || [];
    var out = [];
    rows.forEach(function(r){
        if(!r.compte) return;
        var soldeSigne = (r.sd||0) - (r.sc||0);
        var soldeRetenu = mode === 'signe' ? soldeSigne : Math.abs(soldeSigne);
        var selectionne = soldeRetenu >= seuil && seuil > 0;
        var pcg = coherencePCG(r.compte, soldeSigne);
        out.push({compte:r.compte, intitule:r.intitule, sd:r.sd||0, sc:r.sc||0, soldeSigne:soldeSigne, soldeRetenu:soldeRetenu, selectionne:selectionne, pcg:pcg});
    });
    out.sort(function(a,b){ return Math.abs(b.soldeSigne) - Math.abs(a.soldeSigne); });
    comptesSelectionnesData = out.filter(function(r){ return r.selectionne; });
    var nbIncoherents = out.filter(function(r){ return r.pcg.incoherent; }).length;

    setText('sel-seuil-applique', fmt(seuil));
    setText('sel-nb-total', rows.length);
    setText('sel-nb-select', comptesSelectionnesData.length);
    setText('sel-nb-incoherents', nbIncoherents);

    var table = document.getElementById('selection-comptes-table');
    var html = '<tr><th>N° Compte</th><th>Intitulé</th><th>Solde Débiteur</th><th>Solde Créditeur</th><th>Solde retenu</th><th>Statut</th><th>Cohérence PCG</th><th>🔍 Analyse</th></tr>';
    if(out.length === 0){
        html += '<tr><td colspan="8" style="text-align:center;color:#888;">Aucun compte dans la Balance N. Renseignez d\'abord l\'onglet BALANCE N.</td></tr>';
    } else {
        out.forEach(function(r){
            var ficheBtn = '<button type="button" class="btn btn-primary" style="margin:0;padding:4px 8px;font-size:11px;" onclick="showFicheCompte(\''+esc(r.compte)+'\')">🔍 Voir</button>';
            html += '<tr'+((r.selectionne||r.pcg.incoherent)?' style="background:'+(r.pcg.incoherent?'#fdecea':'#eafaf1')+';"':'')+'>'+
                '<td>'+esc(r.compte)+'</td><td>'+esc(r.intitule)+'</td>'+
                '<td class="number">'+fmt(r.sd)+'</td><td class="number">'+fmt(r.sc)+'</td>'+
                '<td class="number">'+fmt(r.soldeRetenu)+'</td>'+
                '<td>'+(r.selectionne?'<span class="status-ok">✓ Sélectionné (≥ seuil)</span>':'<span style="color:#999;">En dessous du seuil</span>')+'</td>'+
                '<td>'+r.pcg.html+'</td>'+
                '<td>'+ficheBtn+'</td>'+
                '</tr>';
        });
    }
    table.innerHTML = html;

    // Répercute la sélection sur l'onglet de contrôle (périmètre "comptes sélectionnés",
    // liste déroulante du filtre par compte, et tableau des seuils manuels par compte)
    if(typeof renderCtrlCompteSelect === 'function') renderCtrlCompteSelect();
    if(typeof renderSeuilsComptesTable === 'function') renderSeuilsComptesTable();
    if(typeof computeControleGLSondage === 'function') computeControleGLSondage();
}
function exportSelectionComptes(){
    var csv = 'N COMPTE;INTITULE;SOLDE DEBITEUR;SOLDE CREDITEUR;SOLDE RETENU;STATUT;COHERENCE PCG\n';
    comptesSelectionnesData.forEach(function(r){
        var pcgTxt = r.pcg.incoherent ? 'INCOHERENT' : (r.pcg.html.indexOf('variable')>-1 ? 'NON CONTROLE' : (r.pcg.html.indexOf('nul')>-1 ? 'SOLDE NUL' : 'COHERENT'));
        csv += [r.compte,r.intitule,r.sd,r.sc,r.soldeRetenu,'Selectionne',pcgTxt].join(';') + '\n';
    });
    downloadCsv(csv, 'SELECTION_COMPTES_A_AUDITER.csv');
}
